/* Placement variant A: the hero CTA opens the quiz in an accessible dialog.
   Focus is trapped while open, Esc closes, and focus returns to the trigger. */
(function () {
  var modal = document.getElementById("mtd-quiz-modal");
  if (!modal) return;
  /* Look up the hero by its stripe, not by the first h1 in the document: the
     page-gate overlay also carries an h1, and at parse time (before unlock)
     document.querySelector("h1") finds that one and the trigger lookup fails. */
  var hero = document.querySelector(".score-stripe h1");
  hero = hero ? hero.closest(".score-stripe") : null;
  /* Variant A carries an explicit trigger (the secondary "Take the MTD check"
     button); the registered page has none, so it keeps opening from the primary
     checkout link exactly as before. */
  var trigger = hero
    ? hero.querySelector("[data-mtd-quiz-trigger]") ||
      hero.querySelector("a.button-checkout")
    : null;
  if (!trigger) return;

  var closeButtons = modal.querySelectorAll("[data-mtd-modal-close]");
  var focusableSelector =
    'a[href], button:not([disabled]), iframe, input, select, textarea, [tabindex]:not([tabindex="-1"])';
  var previousFocus = null;
  var background = [];

  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-controls", "mtd-quiz-modal");

  function focusable() {
    return Array.prototype.filter.call(
      modal.querySelectorAll(focusableSelector),
      function (element) {
        return element.offsetParent !== null || element === document.activeElement;
      }
    );
  }

  function open(event) {
    event.preventDefault();
    previousFocus = document.activeElement;
    modal.hidden = false;
    document.documentElement.style.overflow = "hidden";
    background = Array.prototype.filter.call(document.body.children, function (node) {
      return node !== modal && node.tagName !== "SCRIPT";
    });
    background.forEach(function (node) {
      if (!node.hasAttribute("inert")) {
        node.setAttribute("inert", "");
        node.setAttribute("data-mtd-modal-inert", "");
      }
    });
    var first = modal.querySelector(".mtd-quiz-modal-close");
    if (first) first.focus();
  }

  function close() {
    if (modal.hidden) return;
    modal.hidden = true;
    document.documentElement.style.overflow = "";
    background.forEach(function (node) {
      if (node.hasAttribute("data-mtd-modal-inert")) {
        node.removeAttribute("inert");
        node.removeAttribute("data-mtd-modal-inert");
      }
    });
    background = [];
    if (previousFocus && previousFocus.focus) previousFocus.focus();
  }

  function onKeydown(event) {
    if (modal.hidden) return;
    if (event.key === "Escape") {
      event.preventDefault();
      close();
      return;
    }
    if (event.key !== "Tab") return;
    var items = focusable();
    if (!items.length) return;
    var first = items[0];
    var last = items[items.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }

  function guardFocus(event) {
    if (modal.hidden || modal.contains(event.target)) return;
    var first = modal.querySelector(".mtd-quiz-modal-close");
    if (first) first.focus();
  }

  function forwardEscape(event) {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
    }
  }

  var frame = document.getElementById("mtd-quiz-modal-frame");
  if (frame) {
    frame.addEventListener("load", function () {
      try {
        frame.contentWindow.addEventListener("keydown", forwardEscape);
      } catch (error) {
        /* file:// opaque origin */
      }
    });
  }

  trigger.addEventListener("click", open);
  Array.prototype.forEach.call(closeButtons, function (button) {
    button.addEventListener("click", close);
  });
  document.addEventListener("keydown", onKeydown);
  document.addEventListener("focusin", guardFocus);
})();

