  font-weight: 500;
  font-style: normal;
  font-display: swap;
}

/* ── Ground: pure black, no extra chrome ───────────────────────────────── */
html,
body {
  background: #000;
}
/* When the quiz is taller than a short viewport the frame itself scrolls
   (quiz-page.css clamps the iframe). Keep that scrollbar thin and quiet so it
   never crowds the dialog's X. */
html {
  scrollbar-width: thin;
  scrollbar-color: #5e5e5e transparent;
}
html::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
html::-webkit-scrollbar-track {
  background: transparent;
}
html::-webkit-scrollbar-thumb {
  background: #5e5e5e;
}
main.solution-finder-host {
  background: #000;
  min-height: 0;
  height: auto;
  overflow: visible;
}

/* The frozen bundle drives type through these custom properties (the `font`
   shorthand). Override the properties themselves so every element that reads
   them picks up the Figma type ramp without fighting per-element specificity. */
:root {
  --quiz-title-font: 900 40px/48px "Sage Headline", "Sage UI", sans-serif;
  --quiz-question-font: 400 26px/42px "Sage Text", "Sage UI", sans-serif;
  --quiz-answer-font: 400 18px/28.8px "Sage Text", "Sage UI", sans-serif;
  --quiz-body-font: 400 16px/24px "Sage Text", "Sage UI", sans-serif;
  --quiz-small-font: 500 14px/21px "Sage UI", sans-serif;
  --quiz-font-family: "Sage Text", "Sage UI", sans-serif;
}

/* Flatten the quiz's centred page gutters: the dialog's 40px padding is the
   only air, so the title and the gradient panel run the full 1440. */
main.solution-finder-host [class*="fGtfKe"] {
  margin: 0;
  padding: 0;
  max-width: none;
  width: 100%;
}
main.solution-finder-host [class~="kyStRA"] {
  padding: 0;
}
main.solution-finder-host [class~="hnTQsX"] {
  padding: 0;
  gap: 0;
}
main.solution-finder-host [class~="lScyZ"] {
  gap: 24px;
  width: 100%;
}

/* ── Title — Sage Headline Black 40/48, centred, 1440 ──────────────────── */
main.solution-finder-host [class*="StyledHeading"] {
  width: 100%;
}
main.solution-finder-host [class*="StyledHeading"] h2,
main.solution-finder-host [class*="StyledHeading"] [class*="sc-dJGLCP"] {
  margin: 0;
  width: 100%;
  /* the `font` shorthand resets every sub-property the bundle may have set */
  font: 900 40px/48px "Sage Headline", "Sage UI", sans-serif;
  color: rgba(255, 255, 255, 0.9);
  text-align: center;
  overflow: visible;
}

/* ── Progress row — 902 wide (Figma), fluid below that ─────────────────── */
main.solution-finder-host [class*="StyledProgress"] {
  width: min(902px, 100%);
  margin: 0 auto;
  padding: 0;
}
main.solution-finder-host [class~="hSoqJU"] {
  display: grid;
  /* Figma: Previous column + 783 track. Fluid: the track takes the remainder
     (minmax(0, 1fr)) so the row's min-content never exceeds the frame at
     laptop widths — a fixed 783px column overflowed the 894px frame at
     1024 and clipped "Step 1 of 7" and the panel's right edge. */
  grid-template-columns: max-content minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 22px;
  row-gap: 4px;
  width: min(902px, 100%);
  height: 43px;
  align-items: start;
  justify-content: start;
}
/* Dissolve the prev+bar wrapper so Previous and the track become grid items. */
main.solution-finder-host [class~="hePGzN"] {
  display: contents;
}
main.solution-finder-host [class*="StyledBack"] {
  grid-column: 1;
  grid-row: 1 / span 2;
  align-self: start;
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 12px 0 7px;
  min-height: 43px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.9);
  font-family: "Sage Text", "Sage UI", sans-serif;
  font-weight: 500;
  font-size: 16px;
  line-height: 1.4;
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 4px;
  cursor: pointer;
}
main.solution-finder-host [class*="StyledBack"][disabled] {
  opacity: 1;
  color: rgba(255, 255, 255, 0.9);
  cursor: default;
}
main.solution-finder-host [class*="StyledBack"] [role="img"] {
  width: 24px;
  height: 24px;
  display: block;
}
main.solution-finder-host [class*="StyledBack"] svg {
  width: 24px;
  height: 24px;
  fill: #fff;
}
main.solution-finder-host [class~="eAvKFB"] {
  grid-column: 2;
  grid-row: 1;
  width: 100%;
  min-width: 0;
}
main.solution-finder-host [class~="hntNzi"],
main.solution-finder-host [class*="hntNzi"] {
  width: 100%;
  margin: 0;
  font: 500 14px/21px "Sage UI", sans-serif;
  color: rgba(255, 255, 255, 0.9);
  text-align: right;
}
main.solution-finder-host [class~="jroPAt"] {
  grid-column: 2;
  grid-row: 2;
  width: 100%;
  min-width: 0;
  height: 4px;
  border-radius: 0;
  background: #777;
  overflow: hidden;
}
/* The fill's width is baked per-step by the bundle; variant-quiz.js rewrites
   it as a % of this 783px track so 1/7 = 112px on step 1. */
main.solution-finder-host [class~="jroPAt"] > div {
  height: 4px;
  border-radius: 0;
  background: #00d639;
}

/* ── Gradient panel — 1440 max (Figma), fluid below ─────────────────────── */
main.solution-finder-host [class*="gomnIV"] {
  width: 100%;
  max-width: 1440px;
  margin: 0;
  padding: 40px;
  border: 1px solid #5e5e5e;
  border-radius: 40px;
  background: #1b1b1b;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 64px;
}
/* The glow art sits behind the content. */
main.solution-finder-host [class*="gomnIV"] [class*="original-glow"] {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}
main.solution-finder-host [class*="gomnIV"] [class*="original-glow"] svg {
  width: 100%;
  height: 100%;
  display: block;
}
main.solution-finder-host [class*="StyledQuestions"],
main.solution-finder-host [class*="gomnIV"] [class*="StyledQuestions"] {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1360px;
  margin: 0;
}

/* ── Q1 line — Sage Text Regular 26/42, centred ────────────────────────── */
main.solution-finder-host [class*="StyledQuestions"] [class*="iLNcwz"] {
  gap: 24px;
  align-items: center;
  justify-items: center;
  width: 100%;
}
main.solution-finder-host [class*="StyledQuestions"] [class*="ewzYfX"],
main.solution-finder-host [class*="StyledQuestions"] [class*="sc-fsYeqr"] {
  font: 400 26px/42px "Sage Text", "Sage UI", sans-serif;
  color: rgba(255, 255, 255, 0.9);
  text-align: center;
  width: 100%;
  max-width: 1360px;
}

/* Helper line is not in the Figma frame — hidden for Variant A. */
main.solution-finder-host .mtd-description,
main.solution-finder-host .mtd-figma-a-hide {
  display: none !important;
}

/* ── Answer cards — 322 × ≥190 (Figma), shrink below that ──────────────── */
main.solution-finder-host [class*="StyledButton"] {
  width: min(322px, 100%);
  min-height: 190px;
  margin: 0;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  border: 2px solid #e2e2e2;
  border-radius: 8px;
  background: #000;
  color: rgba(255, 255, 255, 0.9);
  box-shadow: none;
}
/* One consistent look for the card class (not a .score-button — the quiz's
   own component). Hover/focus/active are defined once here for every card. */
main.solution-finder-host [class*="StyledButton"]:hover {
  border-color: #fff;
}
main.solution-finder-host [class*="StyledButton"]:focus-visible {
  outline: 3px solid #00d639;
  outline-offset: 2px;
}
main.solution-finder-host [class*="StyledButton"]:active {
  border-color: #fff;
}
main.solution-finder-host [class*="StyledButton"] [role="img"] {
  width: 60px;
  height: 60px;
  display: block;
  flex: 0 0 auto;
}
main.solution-finder-host [class*="StyledButton"] [role="img"] svg {
  width: 60px;
  height: 60px;
  display: block;
  fill: #fff;
}
main.solution-finder-host [class*="StyledButton"] [class*="klpehu"],
main.solution-finder-host [class*="StyledButton"] [class*="sc-fsYeqr"] {
  margin: 0;
  font: 400 18px/28.8px "Sage Text", "Sage UI", sans-serif;
  color: rgba(255, 255, 255, 0.9);
  text-align: center;
  width: 100%;
}

/* Answers row: centred, gap 24. */
main.solution-finder-host [class*="cdfGlC"],
main.solution-finder-host [class*="StyledQuestions"] [class*="sc-dmXXqF"]:has(> [class*="StyledButton"]) {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 24px;
  width: 100%;
}

/* ── Tight laptop frames (< 1100) — tighten the air, keep the Figma ramp ──
   Figma 3776:6405 is drawn at 1920; when the FRAME itself is under ~1100
   (a ~1024 window after the dialog's padding) the 40px paddings and 40px
   title squeeze the layout, so drop to the next 4px step. Widths are already
   fluid (min()/100% above); this block only adjusts padding and the title
   step. A 1280 window (frame ~1150) keeps the Figma-exact values. */
@media (max-width: 1099px) {
  main.solution-finder-host [class*="gomnIV"] {
    padding: 24px;
  }
  main.solution-finder-host [class*="StyledHeading"] h2,
  main.solution-finder-host [class*="StyledHeading"] [class*="sc-dJGLCP"] {
    font-size: 32px;
    line-height: 40px;
  }
}

/* Very narrow (< 768): title down another step, cards keep centring and
   wrap to one column if needed. */
@media (max-width: 767px) {
  main.solution-finder-host [class*="gomnIV"] {
    padding: 16px;
    gap: 32px;
  }
  main.solution-finder-host [class*="StyledHeading"] h2,
  main.solution-finder-host [class*="StyledHeading"] [class*="sc-dJGLCP"] {
    font-size: 24px;
    line-height: 32px;
  }
  main.solution-finder-host [class*="StyledQuestions"] [class*="ewzYfX"],
  main.solution-finder-host [class*="StyledQuestions"] [class*="sc-fsYeqr"] {
    font-size: 20px;
    line-height: 30px;
  }
}

