cd /tmp/opencode && python3 - <<'PY'
import re
css=open('/tmp/opencode/refsite-inline.css').read()
rules=re.findall(r'([^{}]+)\{([^{}]*)\}', css)
# print all rules for the 4 button classes and any .before/.after
classes={'kvXfMD','gvAkfe','gOAYXr','jnWVFT'}
def norm(sel):
    return re.sub(r'/*!sc*/','',sel).strip()
for sel, body in rules:
    n=norm(sel)
    if any(c in n for c in classes):
        print("SEL:", n)
        print("  ", n and body.replace('\n',' ').strip())
        print()
PY

