/* MTD quiz placement. All spacing is on the 4px grid; colours come from the
   page's Sage token set (see main.css :root / .theme-dark). */

.mtd-quiz-banner {
  background: var(--theme-background-color);
  color: var(--text-primary-inverse);
}

.mtd-quiz-banner .container {
  padding-top: 16px;
  padding-bottom: 16px;
}

.mtd-quiz-banner-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 24px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-banner-copy {
  min-width: 0;
}

.mtd-quiz-banner-title {
  margin: 0 0 4px;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
}

.mtd-quiz-banner-sub {
  margin: 0;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 16px;
  line-height: 1.4;
}

.mtd-quiz-banner-cta.score-button {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: 999px;
  font-family: inherit;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.mtd-quiz-section {
  background: var(--theme-background-color);
  padding: 32px 0 48px;
  scroll-margin-top: 80px;
}

.mtd-quiz-frame {
  display: block;
  width: 100%;
  min-height: 640px;
  border: 0;
  border-radius: 16px;
  background: var(--theme-background-color);
}

/* Variant A: the quiz in a dialog opened from the hero CTA. */
.mtd-quiz-modal[hidden] {
  display: none;
}

.mtd-quiz-modal {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.mtd-quiz-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
}

.mtd-quiz-modal-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(1200px, 100%);
  max-height: calc(100vh - 48px);
  overflow: hidden;
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 24px;
}

.mtd-quiz-modal-head h2 {
  margin: 0;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 24px;
  line-height: 1.3;
}

.mtd-quiz-modal-close {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
}

.mtd-quiz-modal-foot {
  display: flex;
  justify-content: flex-end;
  padding: 16px 24px;
}

.mtd-quiz-modal-panel .mtd-quiz-frame {
  flex: 1 1 auto;
  height: calc(100vh - 192px);
  min-height: 0;
  border-radius: 0;
}

