/* MTD quiz placement. All spacing is on the 4px grid; colours come from the
   page's Sage token set (see main.css :root / .theme-dark). */

.mtd-quiz-banner {
  background: var(--theme-background-color);
  color: var(--text-primary-inverse);
}

.mtd-quiz-banner .container {
  padding-top: 16px;
  padding-bottom: 16px;
}

.mtd-quiz-banner-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 24px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-banner-copy {
  min-width: 0;
}

.mtd-quiz-banner-title {
  margin: 0 0 4px;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
}

.mtd-quiz-banner-sub {
  margin: 0;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 16px;
  line-height: 1.4;
}

.mtd-quiz-banner-cta.score-button {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: 999px;
  font-family: inherit;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.mtd-quiz-section {
  background: var(--theme-background-color);
  padding: 32px 0 48px;
  scroll-margin-top: 80px;
}

.mtd-quiz-frame {
  display: block;
  width: 100%;
  min-height: 640px;
  border: 0;
  border-radius: 16px;
  background: var(--theme-background-color);
}

/* Variant A: the quiz in a dialog opened from the hero CTA. */
.mtd-quiz-modal[hidden] {
  display: none;
}

.mtd-quiz-modal {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.mtd-quiz-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
}

.mtd-quiz-modal-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(1200px, 100%);
  max-height: calc(100vh - 48px);
  overflow: hidden;
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 24px;
}

.mtd-quiz-modal-head h2 {
  margin: 0;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 24px;
  line-height: 1.3;
}

.mtd-quiz-modal-close {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
}

.mtd-quiz-modal-foot {
  display: flex;
  justify-content: flex-end;
  padding: 16px 24px;
}

.mtd-quiz-modal-panel .mtd-quiz-frame {
  flex: 1 1 auto;
  height: calc(100vh - 192px);
  min-height: 0;
  border-radius: 0;
}

@media (max-width: 767px) {
  .mtd-quiz-banner-card {
    display: block;
    padding: 16px;
  }

  .mtd-quiz-banner-cta.score-button {
    display: inline-block;
    margin-top: 16px;
  }

  .mtd-quiz-section {
    padding: 24px 0 32px;
  }

  .mtd-quiz-frame {
    border-radius: 0;
  }

  .mtd-quiz-modal {
    padding: 16px;
  }

  .mtd-quiz-modal-panel {
    max-height: calc(100vh - 32px);
  }
}

/* The export keeps its <h1> in a breakpoint-hidden wrapper because the hero
   headline is Lottie artwork. Keep exactly one real h1 for assistive tech,
   visually hidden but present in the accessibility tree. */
.score-content-spot.hidden-xs.hidden-sm.hidden-md.hidden-lg:has(> h1) {
  display: block !important;
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  clip-path: inset(50%) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* A5: guarantee a visible keyboard focus ring on every page-level control,
   including controls whose component CSS removes the UA outline. */
body a:focus-visible,
body button:focus-visible,
body input:focus-visible,
body select:focus-visible,
body textarea:focus-visible,
body summary:focus-visible,
body [tabindex]:focus-visible,
body iframe:focus {
  outline: 3px solid var(--sage-brilliant-green) !important;
  outline-offset: 2px !important;
}

/* ── Roadmap 4.17: Variant A / B prototypes (Figma 4.11) ──────────────────
   Styles for the two generated pages in ongoing_project/MTD/variant-a/ and
   variant-b/ (built by ongoing_project/MTD/build-variants.js from this page).
     A  secondary hero CTA "Take the MTD check" that opens the quiz modal;
     B  the gradient HMRC intro at the top and the quiz in the HMRC-letter slot.
   Every rule below is scoped to classes only those generated pages carry, so
   the registered mtd-income-tax page renders exactly as before. */

.mtd-hero-ctas {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 16px;
}



.mtd-quiz-intro {
  padding-top: 40px;
}

.mtd-quiz-intro-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 855px);
  gap: 48px;
  align-items: center;
  padding: 48px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 24px;
  background:
    radial-gradient(120% 130% at 8% 100%, rgba(107, 79, 216, 0.55) 0%, rgba(107, 79, 216, 0) 55%),
    radial-gradient(120% 130% at 96% 60%, rgba(31, 158, 143, 0.55) 0%, rgba(31, 158, 143, 0) 60%),
    linear-gradient(100deg, #0b0b0f 0%, #141420 45%, #0b0b0f 100%);
}

.mtd-quiz-intro-eyebrow {
  display: inline-block;
  margin: 0 0 24px;
  padding: 8px 16px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 999px;
  color: #fff;
  font-size: 16px;
  line-height: 24px;
}

.mtd-quiz-intro-title {
  margin: 0 0 24px;
  color: #fff;
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1.2;
}

.mtd-quiz-intro-accent {
  color: var(--sage-brilliant-green);
}

.mtd-quiz-intro-body {
  max-width: 855px;
  margin: 0 0 32px;
  color: rgba(255, 255, 255, 0.9);
  font-size: 16px;
  line-height: 24px;
}

@media (max-width: 767px) {
  .mtd-quiz-intro {
    padding-top: 24px;
  }

  .mtd-quiz-intro-card {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
    padding: 24px;
  }

  .mtd-hero-ctas {
    gap: 8px;
  }
}

/* Variant A's dialog matches Figma 3776:6405 (panel 1520 × ~597 at 200,242 on
   a 1920 canvas): black fill, 1px #474747 border, 40px radius, 40px padding,
   backdrop near-black, and a 24px X in the top-right corner. The only close
   control is that real <button> — no head/foot chrome. Scoped to the generated
   page so the registered page keeps its approved 1200 shell. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-backdrop {
  background: #000;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-panel {
  width: min(1520px, 100%);
  max-height: calc(100vh - 48px);
  /* The dialog hugs its content: the iframe is fitted to the quiz's rendered
     height by variant-quiz.js, and this box never scrolls — when a viewport is
     too short the iframe itself scrolls (thin scrollbar, see the frame rule),
     so no scrollbar can ever run under the X. */
  overflow: hidden;
  border: 1px solid #474747;
  border-radius: 40px;
  background: #000;
  padding: 40px;
  /* room for the absolutely-positioned close button so it never overlaps the
     quiz title's first line */
  box-sizing: border-box;
}

/* Visually hidden title: the visible one lives inside the quiz iframe; this
   keeps aria-labelledby resolvable in the parent document. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-title-vh {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  clip-path: inset(50%) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* Height is fitted to the quiz content by variant-quiz.js (the quiz's React
   tree mounts asynchronously, so a static height is always wrong). The
   max-height keeps the frame inside the panel when the viewport is short:
   100vh − 48 (modal padding) − 80 (panel padding) − 2 (panel border). Past
   that the frame's own document scrolls with the thin scrollbar defined in
   variant-quiz-figma.css — 40px in from the panel edge, clear of the X. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-panel .mtd-quiz-frame {
  height: auto;
  min-height: 0;
  max-height: calc(100vh - 130px);
  border-radius: 0;
  background: #000;
}

/* The only close control: a bare 24 × 24 button pinned to the dialog's
   top-right, on the 48px padding grid (40 padding + 8). Not a score-button —
   the one-look-per-button-class rule does not apply to it. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close {
  position: absolute;
  top: 48px;
  right: 48px;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  /* the page-wide button rule sets min-width: 96px; the X is 24px */
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: transparent;
  font-size: 0;
  line-height: 0;
  cursor: pointer;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close svg {
  display: block;
  width: 24px;
  height: 24px;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:hover svg,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:focus-visible svg,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:active svg {
  opacity: 0.85;
}

/* The vendor bundle styles every bare <button> (main.css `button:not(…)`):
   a ::after ripple that scales ×400 on :hover/:focus/:active and a filled
   :focus/:active background. The dialog focuses the X on open, so that
   ripple painted a green square behind the icon at every viewport. Kill the
   pseudo-element and keep the button's own box transparent in every state —
   keyboard focus keeps the page's standard plain outline ring (the
   body button:focus-visible rule in this file). */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close::before,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close::after {
  content: none;
  display: none;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:focus,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:active {
  background: transparent;
  color: transparent;
  border: 0;
  outline: none;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:focus-visible {
  outline: 3px solid var(--sage-brilliant-green);
  outline-offset: 2px;
}

/* Laptop widths: the dialog's outer air drops to the next 4px step so the
   quiz keeps its width at ~1024. Frame budget: 100vh − 32 (modal padding)
   − 48 (panel padding) − 2 (panel border). 1280 / 1440 / 1920 keep the
   Figma-exact 24/40 values above. */
@media (max-width: 1199px) {
  .mtd-quiz-modal--figma-a {
    padding: 16px;
  }

  .mtd-quiz-modal--figma-a .mtd-quiz-modal-panel {
    max-height: calc(100vh - 32px);
    padding: 24px;
  }

  .mtd-quiz-modal--figma-a .mtd-quiz-modal-panel .mtd-quiz-frame {
    max-height: calc(100vh - 82px);
  }

  .mtd-quiz-modal--figma-a .mtd-quiz-modal-close {
    top: 32px;
    right: 32px;
  }
}

/* Layout only (no button state): pricing-card CTAs fill the card width. States come from the shared button class. */
.sage-product-card-outer .sage-product-card-cta-wrapper-alt .score-button {
  width: 100%;
}

/* Variant A / B only — advance the embedded quiz past its entry card, and
 * (Variant A only) dress the modal iframe to Figma 3776:6405.
 *
 * Both Figma frames draw the quiz at "Step 1 of 7" (3776:6405 and 3795:3228,
 * referencing 3377:75836 step 1), because the page has already asked the visitor
 * to take the check: Variant A's secondary CTA says "Take the MTD check" and
 * Variant B's intro CTA says "Start the MTD check". The compiled quiz still opens
 * on its own entry card, and it has no deep-link support, so the variant pages
 * click through it once on load to land on the state the design shows.
 *
 * Variant A only (the page carries .mtd-quiz-modal--figma-a):
 *   - inject variant-quiz-figma.css into the modal iframe (fonts, the Figma
 *     layout with fluid widths down to laptop viewports, progress bar, answer
 *     cards — everything the frozen bundle cannot express from the outside);
 *   - fit the iframe height to the quiz's rendered content (the React tree
 *     mounts asynchronously, so a static height is always wrong), re-fitting
 *     on resize and after webfonts load so the dialog hugs its content;
 *   - rewrite the progress fill as a % of the track (the bundle bakes a
 *     pixel width per step from the pre-restyle track);
 *   - swap the two Q1 card icons for the approved 60px light set;
 *   - hide the helper line and the support CTA, which Figma 3776:6405 does not
 *     draw.
 *
 * The registered mtd-income-tax page does not load this file.
 */
(function () {
  var FRAMES = ["mtd-quiz-frame", "mtd-quiz-modal-frame"];
  var ENTRY = /start your mtd check/i;
  var TRIES = 40; // 250ms apart (~10s) — the vendor bundle mounts asynchronously

  function advance(frame) {
    if (frame.dataset.mtdAdvanced === "1") return true;
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return false; // opaque origin; nothing to drive
    }
    if (!doc || !doc.body) return false;
    var candidates = doc.querySelectorAll("button, a, [role='button']");
    for (var i = 0; i < candidates.length; i++) {
      var el = candidates[i];
      if (ENTRY.test((el.textContent || "").replace(/\s+/g, " ").trim())) {
        frame.dataset.mtdAdvanced = "1";
        el.click();
        return true;
      }
    }
    return false;
  }

  /* ── Variant A modal dressing (Figma 3776:6405) ─────────────────────── */

  function isFigmaAModal(frame) {
    return (
      frame.id === "mtd-quiz-modal-frame" &&
      document.querySelector(".mtd-quiz-modal--figma-a")
    );
  }

  function ensureFigmaCss(frame) {
    if (frame.dataset.mtdFigmaCss === "1") return;
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.head) return;
    var link = doc.createElement("link");
    link.rel = "stylesheet";
    link.href = "../variant-quiz-figma.css";
    doc.head.appendChild(link);
    frame.dataset.mtdFigmaCss = "1";
  }

  /* Copy of quiz-frame.js's fitter, pointed at the modal iframe. The quiz's
     main is height:auto once the injected CSS has cleared min-height, so
     body.scrollHeight is the real content box.
     Measure the BODY only, never documentElement: the document element's
     scrollHeight is at least the iframe's current client height, so including
     it makes the height ratchet — an early tall measurement (before the
     injected Figma CSS collapses the layout) locked the frame at ~720px and
     left empty black space under the panel that the dialog then hugged. */
  function fitModalFrame(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.body || !doc.documentElement) return;
    var bodyHeight = doc.body.scrollHeight;
    var layoutHeight = Math.ceil(doc.body.getBoundingClientRect().height);
    var height = Math.max(bodyHeight, layoutHeight, 480);
    if (height > 0) frame.style.height = height + "px";
  }

  /* The green fill's width is baked into a styled-components class at render
     time from the pre-restyle 1272px track. After the injected CSS narrows the
     track to 783px, rewrite the fill as a % of the track so step 1 is
     783/7 ≈ 112px and later steps stay proportional. */
  function fixProgressFill(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.body) return;
    var m = /Step\s+(\d+)\s+of\s+(\d+)/i.exec(doc.body.innerText || "");
    if (!m) return;
    var pct = Number(m[1]) / Number(m[2]);
    var track = doc.querySelector('[class~="jroPAt"]');
    var green = track && track.firstElementChild;
    if (green) green.style.width = (pct * 100).toFixed(4) + "%";
  }

  /* Q1 uses the approved detailed-icon set (mail-opened, question-circle at
     60px, light = white). The frozen bundle ships different kit icons; swap
     them once the Q1 screen is on. Other questions keep the bundle's own
     icons. Paths are relative to THIS page (variant-a/index.html sits beside
     mtd-income-tax/), not to the quiz iframe document. */
  var ICONS = {
    mail: "../mtd-income-tax/assets/m-n-o-mail-opened--60--light.svg",
    question: "../mtd-income-tax/assets/p-q-r-question-circle--60--light.svg"
  };
  var iconCache = {};

  function fetchIcon(name) {
    if (iconCache[name]) return iconCache[name];
    iconCache[name] = fetch(ICONS[name])
      .then(function (r) {
        return r.text();
      })
      .catch(function () {
        return "";
      });
    return iconCache[name];
  }

  function swapQ1Icons(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.body) return;
    if (!/Q1\./.test(doc.body.innerText || "")) return;
    var cards = doc.querySelectorAll(
      '[class*="StyledButton-sc-d53fa8c3-4"]'
    );
    if (cards.length < 2) return;
    if (cards[0].dataset.mtdIcon === "mail") return;
    Promise.all([fetchIcon("mail"), fetchIcon("question")]).then(function (svgs) {
      if (!svgs[0] || !svgs[1]) return;
      var s1 = cards[0].querySelector('[role="img"]');
      var s2 = cards[1].querySelector('[role="img"]');
      if (s1) {
        s1.innerHTML = svgs[0];
        s1.dataset.mtdIcon = "mail";
      }
      if (s2) {
        s2.innerHTML = svgs[1];
        s2.dataset.mtdIcon = "question";
      }
      fitModalFrame(frame);
    });
  }

  /* Figma 3776:6405 has no helper line under Q1 and no support CTA. */
  function hideFigmaExtras(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc) return;
    var desc = doc.querySelectorAll(".mtd-description");
    for (var i = 0; i < desc.length; i++) desc[i].classList.add("mtd-figma-a-hide");
    var support = doc.querySelectorAll(
      '[class*="sc-kZOrUD"], [class*="jqYjtI"]'
    );
    for (var j = 0; j < support.length; j++) {
      var el = support[j];
      if (/get in touch for support/i.test(el.textContent || "")) {
        el.classList.add("mtd-figma-a-hide");
      }
    }
  }

  function dressFigmaAModal(frame) {
    ensureFigmaCss(frame);
    hideFigmaExtras(frame);
    swapQ1Icons(frame);
    fixProgressFill(frame);
    fitModalFrame(frame);
    /* Sage Headline/Text swap in after first paint and reflow the title and
       the card copy — re-fit once the quiz document's fonts have settled. */
    if (frame.dataset.mtdFontsFit !== "1") {
      var doc;
      try {
        doc = frame.contentDocument;
      } catch (error) {
        doc = null;
      }
      if (doc && doc.fonts && doc.fonts.ready) {
        frame.dataset.mtdFontsFit = "1";
        doc.fonts.ready.then(function () {
          fitModalFrame(frame);
        });
      }
    }
  }

  /* The quiz re-wraps when the dialog's width changes with the window, so the
     fitted height has to follow. Debounced to one re-dress per resize burst. */
  var resizeTimer = null;
  window.addEventListener("resize", function () {
    if (resizeTimer) clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      resizeTimer = null;
      FRAMES.forEach(function (id) {
        var frame = document.getElementById(id);
        if (frame && isFigmaAModal(frame)) dressFigmaAModal(frame);
      });
    }, 150);
  });

  var tries = 0;
  var timer = setInterval(function () {
    tries += 1;
    var pending = false;
    FRAMES.forEach(function (id) {
      var frame = document.getElementById(id);
      if (!frame) return;
      if (!advance(frame)) pending = true;
      if (isFigmaAModal(frame)) dressFigmaAModal(frame);
    });
    /* Keep the interval alive while the modal is still dressing (the React
       tree re-renders after the entry click, so Q1 appears a beat later);
       stop once both frames have advanced and the fitter has had a few more
       ticks to settle, or after TRIES. */
    var modal = document.getElementById("mtd-quiz-modal-frame");
    var dressing = isFigmaAModal(modal) && modal && modal.dataset.mtdAdvanced === "1" && tries < TRIES + 20;
    if ((!pending && !dressing) || tries >= TRIES + 20) clearInterval(timer);
  }, 250);

  /* The quiz re-renders on every answer click; keep the fitter and the progress
     fill in sync after that. */
  document.addEventListener("mtd-quiz:event", function () {
    FRAMES.forEach(function (id) {
      var frame = document.getElementById(id);
      if (frame && isFigmaAModal(frame)) dressFigmaAModal(frame);
    });
  });
})();

